def parse(inp, sep_color=7):
    G=[[int(x) for x in r.split()] for r in inp.strip().split('\n')]
    seps=[i for i,row in enumerate(G) if all(v==sep_color for v in row)]
    bands=[]; start=0
    for s in seps+[len(G)]:
        if s>start: bands.append(list(range(start,s)))
        start=s+1
    groups=[list(range(0,3)),list(range(4,7)),list(range(8,11)),list(range(12,15))]
    return G,bands,groups

